 "content": "from collections import Counter


def transform(grid):
    """Decode a grid of 3x3 color swatches against its global background."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3 or any(len(row) != w for row in grid):
        raise ValueError("grid dimensions must be rectangular multiples of 3")
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    output = []
    for r in range(0, h, 3):
        out_row = []
        for c in range(0, w, 3):
            counts = Counter(value for row in grid[r:r + 3] for value in row[c:c + 3] if value != background)
            if not counts:
                out_row.append(background)
            else:
                # When a tile has multiple foreground colors, the strongest
                # represented color is the one with the highest tile count.
                out_row.append(counts.most_common(1)[0][0])
        output.append(out_row)
    return output
